#!/usr/bin/env python3
"""rest-parameters.py <seed>: A TYPED program: functions with a rest parameter of many element types, entered by a direct call, a closure in a variable, a method, a spread, call | apply | bind, new; handed whole numbers, fractions, every road to NaN, -0, infinities, what stands for undefined | null | absent among raw numbers (an element beyond the end, an optional member, an optional parameter), and lies under `as`. Each array is then asked everything in which a hole, a NaN and an undefined differ. As plain Bun or a throw. (No `undefined as number`: a cast between primitives converts under --aot.)"""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
R = random.Random(seed)
ELEMENT = ['number', 'number', 'number', 'number | undefined', 'number | null', 'number | undefined | null', 'unknown', 'any', 'number | string', 'string', 'boolean', 'bigint | number']
NUMS = ['1', '2.5', '-0', '0', 'NaN', '0 / zero', 'Infinity', '-Infinity', '1e300 * 1e10', 'Number("x")', 'Math.sqrt(-1)', 'undef + 1', '(undef as number) * 2', 'values[1]', 'values[9]', 'values[-1]', 'fractions[0]', 'fractions[7]', 'holder.opt', 'holder.set', 'full.opt', 'maybe(3)', 'nil', 'nothing', 'i', 'i + 0.5', 'i | 0', 'i / 2', '2147483647 + i', '-2147483648 - i', 'f64[0]', 'f64[1]', 'f64[5]', 'i32[0]', 'parseFloat("1.5")', 'parseInt("z")', 'holes[1]', 'holes[0]', 'Number.MIN_VALUE', '4294967296', 'nanWithBits(1)', 'nanWithBits(2)', 'nanWithBits(3)', 'nanWithBits(i)', 'opt2?.deep', 'fromJson.a', 'fromJson.b', 'fromJson.c']
OTHERS = ['"s"', 'true', 'null', 'undefined', '{}', '[1]', '10n', 'Symbol.iterator']
def raw(x): return '(%s)!' % x if x in ('holder.opt', 'full.opt', 'opt2?.deep') else x
out = []
w = out.append
w('// generated by rest-parameters.py %d' % seed)
w('declare const console: { log(...values: unknown[]): void };')
w('const show = (v: unknown): string => (v === null ? "null" : v === undefined ? "u" : typeof v === "number" ? (Object.is(v, -0) ? "-0" : String(v)) : typeof v === "string" ? JSON.stringify(v) : typeof v === "bigint" ? v + "n" : typeof v === "symbol" ? "sym" : Array.isArray(v) ? "[" + Array.from(v, show).join() + "]" : typeof v === "object" ? "{}" : String(v));')
w('const zero: number = [0][0]!; const undef = undefined as unknown as number; const nil = null as unknown as number; const nothing = (void 0) as unknown as number;')
w('const values: number[] = [1, 2, 3]; const fractions: number[] = [0.5, 1.5]; const holes: number[] = [1, , 3] as number[]; const f64 = new Float64Array([0.25, NaN]); const i32 = new Int32Array([7]);')
w('interface Holder { set: number; opt?: number } const holder: Holder = { set: 4 }; const full: Holder = { set: 5, opt: 6.5 }; const opt2: { deep: number } | undefined = zero === 0 ? undefined : { deep: 1 };')
w('function maybe(n?: number): number { return n as number; }')
w('const fromJson = JSON.parse(\'{"a":1.5,"b":null}\') as { a: number; b: number; c: number };')
w('const bits = new BigUint64Array(1); const asDouble = new Float64Array(bits.buffer);')
w('function nanWithBits(k: number): number { bits[0] = 0x7ff8000000000000n + BigInt(k) ; const a = asDouble[0]!; bits[0] = 0xfff8000000000000n + BigInt(k * 3); return k & 1 ? a : asDouble[0]!; }')
w('function ask(xs: readonly unknown[]): string {')
w('  const a = xs as unknown[]; let seen = 0; a.forEach(() => { seen++; }); let own = ""; for (let k = 0; k < a.length + 1; k++) own += (k in a ? "1" : "0") + (Object.prototype.hasOwnProperty.call(a, k) ? "1" : "0");')
w('  let s = 0; for (const v of a) if (typeof v === "number") s += v;')
w('  return [a.length, seen, own, show(a), JSON.stringify(a, (_k, v) => (typeof v === "bigint" ? "n" : v)), a.includes(NaN), a.indexOf(NaN), a.includes(undefined), a.indexOf(undefined), a.lastIndexOf(0), Object.keys(a).join(""), show(s), show(a[0]), show(a[a.length - 1]), show(a[a.length]), a.findIndex(v => v === undefined), a.filter(() => true).length, show(a.slice().reverse()), show([...a]), show(a.concat([1.5])), a.join("|"), Array.isArray(a), a.every(v => typeof v === "number"), show(a.flat()), show(Object.entries(a).length)].join(" ");')
w('}')
w('function later(xs: unknown[]): string { const before = ask(xs); xs.push("tail"); xs[xs.length + 1] = 1; xs.unshift(undefined); const grown = ask(xs); xs.length = 1; xs[0] = NaN; return before + " / " + grown + " / " + ask(xs); }')
N = 10
kinds = []
for n in range(N):
    e = R.choice(ELEMENT); named = R.randrange(3); kinds.append((e, named))
    head = ''.join('p%d: number, ' % k for k in range(named))
    body = R.choice(['return ask(xs);', 'return later(xs as unknown[]);', 'let t = 0; for (let k = 0; k < xs.length; k++) { const v = xs[k]; if (typeof v === "number") t += v; } return show(t) + " " + ask(xs);', 'const kept = xs; return ask(kept) + " " + show(kept[0]) + show(kept[1]);', 'return ask(xs.map(v => v)) + " " + ask(xs);', 'xs[0] = xs[1] as never; return ask(xs);', 'return show(xs.length) + show(xs[0]) + show(xs[1]) + show(xs[2]) + " " + ask(xs);'])
    w('function f%d(%s...xs: (%s)[]): string { %s }' % (n, head, e, body))
    w('const c%d = (%s...xs: (%s)[]): string => { %s };' % (n, head, e, body))
    w('class K%d { tag = %d; m(%s...xs: (%s)[]): string { %s } static s(%s...xs: (%s)[]): string { %s } constructor(...xs: (%s)[]) { made.push(ask(xs)); } }' % (n, n, head, e, body, head, e, body, e))
out.insert(len(out) - 3 * N, 'const made: string[] = [];')
w('function tuple(...xs: [number, number?, ...number[]]): string { return ask(xs); }')
w('function generic<T extends number[]>(...xs: T): string { return ask(xs); }')
w('function sum(...xs: number[]): number { let t = 0; for (let k = 0; k < xs.length; k++) t += xs[k]!; return t; }')
w('const attempt = (f: () => unknown): string => { try { return String(f()); } catch (e) { return "THROWS " + (e as Error).name; } };')
w('let line = 0; const say = (f: () => unknown): void => { console.log(line++ + ": " + attempt(f)); };')
w('for (let i = 0; i < 3; i++) {')
for row in range(90):
    n = R.randrange(N); e, named = kinds[n]
    count = R.choice([0, 1, 1, 2, 3, 3, 4, 6, 9, 17])
    pool = NUMS if (e.startswith('number') and 'string' not in e) or R.random() < 0.6 else NUMS + OTHERS * 3
    args = ['%d' % k for k in range(named)] + ['(%s) as never' % R.choice(pool) if R.random() < 0.5 or pool is not NUMS or 'number' not in e else raw(R.choice([x for x in NUMS if x not in ('nil', 'nothing')])) for _ in range(count)]
    a = ', '.join(args)
    how = R.randrange(11)
    call = ['f%d(%s)' % (n, a), 'c%d(%s)' % (n, a), 'new K%d().m(%s)' % (n, a), 'K%d.s(%s)' % (n, a), '(f%d as (...a: never[]) => string)(...([%s] as never[]))' % (n, a), 'f%d.call(null, %s)' % (n, a) if a else 'f%d.call(null)' % n, 'f%d.apply(null, [%s] as never)' % (n, a), '(f%d.bind(null%s) as () => string)()' % (n, ', ' + a if a else ''), '(new K%d(%s), made.pop())' % (n, ', '.join(args[named:])), '[f%d, c%d][i & 1]!(%s)' % (n, n, a), 'Reflect.apply(c%d, null, [%s])' % (n, a)][how]
    w('  say(() => %s);' % call)
for row in range(14):
    args = ', '.join(raw(R.choice([x for x in NUMS if x not in ('nil', 'nothing')])) for _ in range(R.choice([1, 2, 3, 5])))
    w('  say(() => %s(%s));' % (R.choice(['tuple', 'generic', 'sum', 'show(sum', 'Math.max', 'Math.min'])[0:], args) if False else '  say(() => show(%s(%s)));' % (R.choice(['tuple', 'generic', 'sum', 'Math.max', 'Math.min', 'Math.hypot']), args))
w('}')
print('\n'.join(out))
